/// <summary>
/// Extension of GeneralJournalAccountEntry table.
/// </summary>
[ExtensionOf(tableStr(GeneralJournalAccountEntry))]
internal final class METGeneralJournalAccountEntry_Extension
{
}

Method.Source:
    /// <summary>
    /// Calculates the internal values for the current record.
    /// </summary>
    /// <param name="_reverseOppositeSignAmounts">
    /// true if opposite signed transactions are not supported; otherwise, false. Optional.
    /// </param>
    /// <remarks>
    /// These calculations are done manually to avoid an <c>insert</c> method override which would affect performance.
    /// </remarks>
    public void calculateInternalValues(boolean _reverseOppositeSignAmounts )
    {
        next calculateInternalValues(_reverseOppositeSignAmounts);


        if(this.PostingType == LedgerPostingType::InventStdCostChangeVariance)
        {
            InventSiteLockedDimensionValueSet   warehouseDim;
            DimensionAttributeValueCombination  dimAttrValueCombo;
            DimensionDisplayValue               profitValue,businessUnitValue,CostCentreValue,mainAccountValue,itemGroupValue,pillarValue;
            container                           conValue;

            warehouseDim    = METTransferOrderVoucherHelperClass::getWarehouseDefaultDim(this);
            profitValue     = METTransferOrderVoucherHelperClass::getProfitDimensionValue(warehouseDim);

            if(profitValue)
            {
                mainAccountValue    = METTransferOrderVoucherHelperClass::getIndividualDimValues("@SYS343426", this.LedgerDimension);
                businessUnitValue   = METTransferOrderVoucherHelperClass::getIndividualDimValues("@SYS343395", this.LedgerDimension);
                CostCentreValue     = METTransferOrderVoucherHelperClass::getIndividualDimValues("@SYS343410", this.LedgerDimension);
                itemGroupValue      = METTransferOrderVoucherHelperClass::getIndividualDimValues("@MET:ItemGroup", this.LedgerDimension);
                pillarValue         = METTransferOrderVoucherHelperClass::getIndividualDimValues("@MET:Pillar", this.LedgerDimension);

                conValue = [businessUnitValue,CostCentreValue,itemGroupValue,pillarValue,profitValue];
                this.LedgerDimension = METTransferOrderVoucherHelperClass::generateLedgerDimension(conValue,mainAccountValue);

                select firstOnly DisplayValue, MainAccount from dimAttrValueCombo
                    where dimAttrValueCombo.RecId == this.LedgerDimension;

                this.LedgerAccount  = dimAttrValueCombo.DisplayValue;
                this.MainAccount    = dimAttrValueCombo.MainAccount;
            }
        }
    }
